import{_ as a,c as e,o as t,a1 as r,em as n}from"./chunks/framework.B-lSKjqC.js";const h=JSON.parse('{"title":"Webbutveckling 1","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/1-intro/index.md","filePath":"web1/1-intro/index.md"}'),s={name:"web1/1-intro/index.md"},i=r('<h1 id="webbutveckling-1" tabindex="-1">Webbutveckling 1 <a class="header-anchor" href="#webbutveckling-1" aria-label="Permalink to &quot;Webbutveckling 1&quot;">​</a></h1><h2 id="introduktion" tabindex="-1">Introduktion <a class="header-anchor" href="#introduktion" aria-label="Permalink to &quot;Introduktion&quot;">​</a></h2><p><span class="a">Välkommen till kursen Webbutveckling 1!</span></p><p align="center"><img src="'+n+'" alt="Webbutveckling 1 bild"></p><p>Denna kurs är byggd enligt <span class="a">Skolverkets kursdokument gällande ämnesplan</span> för Webbutveckling 1 och syftar till att ge dig en <strong>grundläggande</strong> förståelse för webbutveckling och de tekniker som används för att skapa <span class="a">moderna</span>, <span class="a">responsiva</span> och <span class="a">användarvänliga</span> webbplatser.</p><p>Du kommer <span class="a">att arbeta med de grundläggande byggstenarna HTML och CSS</span> för att skapa struktur och designa webbplatser. Dessa tekniker ger dig möjlighet att bygga sidor som inte bara ser bra ut, utan också fungerar bra på olika enheter, från <strong>datorer</strong> till <strong>mobiler</strong> och <strong>surfplattor</strong>. Du kommer <span class="a">att lära dig hur du skapar responsiva och tillgängliga webbplatser som anpassar sig efter skärmstorlek och användarens behov</span>.</p><p>Kursen går även igenom <span class="a">hur man planerar ett webbtekniskt projekt</span>. Du får insikt i <span class="a">hur du strukturerar och planerar en webbplats</span> med hjälp av etablerade tekniker och metoder, för att säkerställa att din webbplats är både tekniskt hållbar och användarvänlig.</p><p>Vi kommer att titta på <span class="a">internettekniker och webbens historik</span>, för att ge dig en förståelse för hur webben har utvecklats och var vi står idag. Du kommer även <span class="a">att lära dig vikten av kodvalidering och kvalitetssäkring</span> för att säkerställa att din kod fungerar korrekt och är fri från fel.</p><p>Grafik och optimering är också viktiga delar av kursen. Du kommer <span class="a">att lära dig hur du använder grafik på ett effektivt sätt på webben</span> och hur du <span class="a">optimerar sidor för att de ska ladda snabbt och vara prestandavänliga</span>, vilket är avgörande för en bra användarupplevelse.</p><p>Etik och integritet på nätet, samt frågor kring upphovsrätt och gällande lagar, kommer också att behandlas. <span class="a">Du får en förståelse för de juridiska och etiska aspekterna av webbutveckling</span>, så att du kan skapa webbplatser på ett ansvarsfullt sätt.</p><p>Genom både <span class="a">teoretiska</span> och <span class="a">praktiska moment</span> kommer du att utveckla dina tekniska färdigheter och förståelse för hur man skapar moderna, användarvänliga och lagliga webbplatser.</p><p><span class="a">Kursen ger dig en solid grund för att fortsätta utvecklas inom webbutveckling</span>, oavsett om du sikta på att bli webbutvecklare eller bara vill förstå hur webben fungerar.</p><p><strong>Vi ser fram emot att påbörja denna resa in i webbutvecklingens värld tillsammans</strong>!</p><p>Lycka till! 😎 👊 👍</p>',14),l=[i];function o(p,k,d,c,g,b){return t(),e("div",null,l)}const m=a(s,[["render",o]]);export{h as __pageData,m as default};
